Evaluation metrics for lost_in_conversation benchmark.

Metrics:
  P-bar: mean score across all conversations
  A90: performance at 90th percentile turn count (long conversations)
  U10_90: uniformity gap between early and late conversations

Input: list of dicts with keys 'score', 'num_turns'
Dependencies: numpy
"""
import numpy as np
from typing import List, Dict, Any, Optional


def compute_p_bar(results: List[Dict[str, Any]]) -> float:
    scores = [r["score"] for r in results if r.get("score") is not None]
    if not scores:
        return 0.0
    return float(np.mean(scores))


def compute_a90(results: List[Dict[str, Any]]) -> float:
    valid = [(r["score"], r["num_turns"]) for r in results if r.get("score") is not None]
    if not valid:
        return 0.0
    scores, turns = zip(*valid)
    p90_turns = np.percentile(turns, 90)
    a90_scores = [s for s, t in zip(scores, turns) if t >= p90_turns]
    return float(np.mean(a90_scores)) if a90_scores else 0.0


def compute_u10_90(results: List[Dict[str, Any]]) -> float:
    valid = [(r["score"], r["num_turns"]) for r in results if r.get("score") is not None]
    if not valid:
        return 0.0
    scores, turns = zip(*valid)
    p10 = np.percentile(turns, 10)
    p90 = np.percentile(turns, 90)
    early = [s for s, t in zip(scores, turns) if t <= p10]
    late = [s for s, t in zip(scores, turns) if t >= p90]
    if not early or not late:
        return 0.0
    return float(np.mean(early) - np.mean(late))


def compute_all_metrics(results: List[Dict[str, Any]]) -> Dict[str, Any]:
    return {
        "p_bar": compute_p_bar(results),
        "a90": compute_a90(results),
        "u10_90": compute_u10_90(results),
        "n_samples": len(results),
        "n_correct": sum(1 for r in results if r.get("is_correct", False)),
    }


def compute_per_task_metrics(results: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    tasks = {}
    for r in results:
        task = r.get("task", "unknown")
        if task not in tasks:
            tasks[task] = []
        tasks[task].append(r)
    return {task: compute_all_metrics(task_results) for task, task_results in tasks.items()}


