        {"score": 1.0, "num_turns": 6, "is_correct": True, "task": "math"},
        {"score": 0.0, "num_turns": 10, "is_correct": False, "task": "math"},
    ]
    print("=== All metrics ===")
    m = compute_all_metrics(mock_results)
    for k, v in m.items():
        print(f"  {k}: {v}")
    print("\n=== Per-task metrics ===")
    pt = compute_per_task_metrics(mock_results)
    for task, metrics in pt.items():
        print(f"  {task}:")
        for k, v in metrics.items():
            print(f"    {k}: {v}")
